using Microsoft.EntityFrameworkCore;

class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos("AccountEndpoint=...;AccountKey=...", "MyDatabase");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change: EF Core 9 renamed the default discriminator from
        // "Discriminator" to "$type". Existing documents use "Discriminator",
        // so we must explicitly preserve the old property name.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Breaking change: EF Core 9 no longer embeds the discriminator in the
        // JSON `id` property. Existing documents have "Session|<key>" format.
        // Preserve old format so existing documents remain accessible.
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}

class Session
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
}

// Breaking change: Cosmos DB provider no longer supports synchronous I/O.
// All sync calls (ToList, SaveChanges, First, etc.) now throw at runtime.
// Convert to async equivalents:
class CosmosQueryService
{
    private readonly CosmosDbContext _db;

    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // BEFORE (breaks in EF Core 9):
    //   var sessions = _db.Sessions.Where(s => s.Name == name).ToList();
    //   _db.SaveChanges();

    // AFTER (use async):
    public async Task<List<Session>> GetSessionsAsync(string name)
        => await _db.Sessions.Where(s => s.Name == name).ToListAsync();

    public async Task SaveAsync()
        => await _db.SaveChangesAsync();
}

